    @staticmethod
    def opening_has_data_citation(body):
        """Whether the first sentence contains an index or contract-history citation."""
        match = re.search(r"[.!?](?=\s|$)", body)
        opening = body[:match.end()] if match else body
        return re.search(r"\b(?:idx|ctr):[\w.:@#/-]*\w", opening) is not None

    @staticmethod
    def _format_evidence(entry):
        return (
            f"{entry['series']}: {entry['delta_pct']:+.1f}% from {entry['start_month']} to "
            f"{entry['end_month']} ({entry['start_id']}, {entry['end_id']}); "
            f"cost-driver weight={entry.get('weight', 0):g}"
        )

    def data_rebuttal_line(self, events=None):
        """A ready-to-use sentence containing only code-verified index values and citable IDs."""
        if not self._evidence:
            return ""
        selected = sorted(self._evidence, key=lambda e: e.get("weight", 0), reverse=True)[:2]
        evidence = " ".join(
            f"{e['series']} changed {e['delta_pct']:+.1f}% from {e['start_month']} to "
            f"{e['end_month']} ({e['start_id']}, {e['end_id']})."
            for e in selected
        )
        claim = self.supplier_percentage_claim(events) if events else None
        if claim:
            return f"Your email cites a {claim} increase. {evidence} Could you help reconcile the difference?"
        return evidence

    @staticmethod
    def supplier_percentage_claim(events):
        """Return a percentage explicitly stated in the supplier's latest email, if any."""
        if not events:
            return None
        body = latest(events).get("body", "")
        for match in re.finditer(r"([+-]?\d+(?:[.,]\d+)?)\s*%", body):
            context = body[max(0, match.start() - 80):match.end() + 80].lower()
            if any(word in context for word in ("price", "cost", "inflation", "increase", "rise", "surcharge", "material")):
                return f"{match.group(1).replace(',', '.')}%"
        return None

    def contract_rebuttal_line(self, case, sid, terms):
        """Compare a quote with a citable historical purchase for the same supplier and part."""
        candidates = []
        parts = set(case.get("parts", []))
        price_fields = (
            "unit_price", "price_per_unit", "unit_price_eur", "price_eur",
            "price_eur_per_unit", "agreed_unit_price",
        )
        date_fields = ("date", "month", "valid_from", "contract_date", "ordered_at")
        for wrapped in self._contracts:
            row = {k.lower(): v for k, v in wrapped.items()}
            row_id = row.get("id") or next(
                (value for value in wrapped.values() if isinstance(value, str) and ID_RE.fullmatch(value)),
                None,
            )
            if not row_id or not self.fact(case, row_id):
                continue
            supplier = row.get("supplier_id", row.get("supplier"))
            part = row.get("part_id", row.get("part"))
            if supplier != sid:
                continue
            if part not in parts:
                continue
            historical_price = next((row[k] for k in price_fields if row.get(k) is not None), None)
            if historical_price is None:
                continue
            try:
                historical_price = float(historical_price)
                current_price = float((terms or {}).get("unit_price"))
            except (TypeError, ValueError):
                continue
            if historical_price <= 0 or current_price <= 0:
                continue
            date_value = next((row[k] for k in date_fields if row.get(k) is not None), None)
            candidates.append((str(date_value or ""), historical_price, current_price, row_id))
        if not candidates:
            return ""
        date_value, historical_price, current_price, row_id = max(candidates)
        change = (current_price / historical_price - 1) * 100
        date_text = f" dated {date_value}" if date_value else ""
        return (
            f"Our last matched purchase record lists EUR {historical_price:.2f}/unit{date_text} "
            f"({row_id}); your current quote is {change:+.1f}% against that record."
        )

    def _state(self, case, sid, events):
        sheet_id, terms = standing(events)
        std = standard_terms(events)
        terms = complete_offer(case, terms) if terms.get("unit_price") is not None else {}
        cost = total_cost(case, terms, std) if terms else math.inf
        valid = bool(terms) and must_haves_ok(case, terms, std)
        target_price = self.target_price(case, terms)
        target_terms = self.offer_terms(case, terms, target_price) if terms else complete_offer(
            case, {"unit_price": target_price}
        )
        # Target cost is filled against this supplier's quoted standard terms below.
        target_cost = total_cost(case, target_terms, std)
        # The actual ceiling is supplier-specific because standard terms affect total cost.
        ceiling = self.max_price_for_cost(case, terms or target_terms, std, self.reference_cost(case, {}))
        return {
            "sheet_id": sheet_id, "terms": terms, "standard": std, "cost": cost, "valid": valid,
            "target_price": min(target_price, ceiling), "target_cost": target_cost,
            "ceiling_price": ceiling,
        }

    def target_price(self, case, terms):
        buyer = case["buyer"]
        current = buyer.get("current_unit_price")
        if current is None:
            alt = buyer.get("alternative") or {}
            current = (alt.get("terms") or {}).get("unit_price") or buyer.get("fallback_unit_price")
        if current is None:
            current = (terms or {}).get("unit_price") or 1.0
        changes = [(e.get("weight", 0), e["delta_pct"]) for e in self._evidence if e.get("weight", 0) > 0]
        total_weight = sum(w for w, _ in changes)
        delta = sum(w * d for w, d in changes) if changes else 0.0
        if total_weight > 1.0:
            delta /= total_weight
        # Pass both cost increases and decreases through to the evidence-based target.
        adjusted = float(current) * (1 + delta / 100)
        return round(max(0.01, adjusted), 2)

    def _batna(self, case, threads, states):
        choices = []
        alt = case["buyer"].get("alternative") or {}
        if alt.get("terms", {}).get("unit_price") is not None and must_haves_ok(case, alt["terms"]):
            c = total_cost(case, alt["terms"])
            choices.append((c, "documented alternative"))
        for sid, events in threads.items():
            sheet_id, terms = standing(events)
            if not sheet_id or terms.get("unit_price") is None:
                continue
            std = standard_terms(events)
            if must_haves_ok(case, terms, std):
                choices.append((total_cost(case, terms, std), f"live quote {sid}"))
        fallback = case["buyer"].get("fallback_unit_price")
        if fallback is not None:
            terms = self.offer_terms(case, {}, fallback)
            if must_haves_ok(case, terms):
                choices.append((total_cost(case, terms), "fallback supply"))
        if not choices:
            return {"cost": math.inf, "source": "no priced alternative"}
        cost, source = min(choices)
        return {"cost": cost, "source": source}

    def reference_cost(self, case, threads):
        return self._batna(case, threads, {})["cost"]

    def max_price_for_cost(self, case, template, standard, cap):
        if not math.isfinite(cap):
            return max(0.01, float((template or {}).get("unit_price") or case["buyer"].get("current_unit_price") or 1) * 2)
        base = dict(template or complete_offer(case, {"unit_price": 1.0}))
        low, high = 0.01, max(100.0, float(base.get("unit_price") or 1.0) * 8)
        for _ in range(48):
            mid = (low + high) / 2
            offer = self.offer_terms(case, base, mid)
            if total_cost(case, offer, standard) <= cap + 0.01:
                low = mid
            else:
                high = mid
        return round(low, 2)

    def offer_terms(self, case, current_terms, price):
        terms = complete_offer(case, {**(current_terms or {}), "unit_price": price})
        options = case.get("term_options", {})
        must_haves = case["buyer"].get("must_haves", [])
        for must in must_haves:
            field, op, required = must["field"], must["op"], must["value"]
            value = terms.get(field)
            if value is not None and OPS[op](value, required):
                continue
            candidates = list(options.get(field, [])) or [required]
            valid = [
                candidate for candidate in candidates
                if OPS[op](snap(case, field, candidate), required)
            ]
            if valid:
                offers = [
                    (total_cost(case, complete_offer(case, {**terms, field: candidate})), candidate)
                    for candidate in valid
                ]
                terms[field] = min(offers, key=lambda item: item[0])[1]
        # Longer payment terms lower the buyer's financing cost. Apply the best available
        # allowed term on every outgoing sheet, while respecting any payment-days must-have.
        if "payment_days" in case.get("negotiable", []):
            candidates = list(options.get("payment_days", []))
            if not candidates:
                candidates = [terms.get("payment_days", case["buyer"].get("reference_payment_days", 0))]
            for must in must_haves:
                if must["field"] == "payment_days":
                    candidates = [
                        candidate for candidate in candidates
                        if OPS[must["op"]](snap(case, "payment_days", candidate), must["value"])
                    ]
            if candidates:
                offers = [
                    (total_cost(case, complete_offer(case, {**terms, "payment_days": candidate})), candidate)
                    for candidate in candidates
                ]
                terms["payment_days"] = min(offers, key=lambda item: item[0])[1]
        return complete_offer(case, terms)

    def cap_offer(self, case, terms, standard, cap):
        if not math.isfinite(cap) or total_cost(case, terms, standard) <= cap + 0.01:
            return terms
        ceiling = self.max_price_for_cost(case, terms, standard, cap)
        return self.offer_terms(case, terms, max(0.01, min(terms.get("unit_price") or ceiling, ceiling)))

    def best_peer_quote(self, case, sid, states):
        peers = [
            (state["cost"], other, state, True)
            for other, state in states.items()
            if other != sid and state["sheet_id"] and state["terms"].get("unit_price") is not None
            and state["valid"]
        ]
        alternative = case["buyer"].get("alternative") or {}
        alternative_terms = alternative.get("terms") or {}
        if alternative_terms.get("unit_price") is not None and must_haves_ok(case, alternative_terms):
            peers.append((
                total_cost(case, alternative_terms),
                alternative.get("ref") or "documented alternative",
                {"terms": alternative_terms, "sheet_id": alternative.get("ref")},
                False,
            ))
        if not peers:
            return None
        _, other, state, is_live = min(peers, key=lambda item: (item[0], str(item[1])))
        return {
            "supplier_id": other if is_live else None,
            "offer_id": state.get("sheet_id"),
            "unit_price": state["terms"]["unit_price"],
            "cost": state.get("cost", total_cost(case, state["terms"])),
            "live": is_live,
        }

    def render(self, case, threads, sid, terms, state, batna, peer, data_line, history_line):
        out = [self.brief, f"\nSELECTED THREAD: {sid}"]
        out.append(f"PYTHON OFFER (binding term sheet): {json.dumps(terms, ensure_ascii=False)}")
        out.append("Internal price thresholds and BATNA are withheld; use only the binding offer shown above.")
        if data_line:
            out.append(f"PYTHON-VERIFIED DATA REBUTTAL: {data_line}")
        if history_line:
            out.append(f"PYTHON-VERIFIED CONTRACT HISTORY COMPARISON: {history_line}")
        if peer:
            source = f"{peer['supplier_id']} offered" if peer["live"] else "The documented alternative is"
            reference = f" ({peer['offer_id']})" if peer.get("offer_id") else ""
            out.append(f"COMPETING ALTERNATIVE: {source} EUR {peer['unit_price']:.2f}/unit{reference}; use it tactfully.")
        out.append("Write the email body only; the strategy, exact offer, and external action are fixed by Python.")
        for thread_id in live_threads(threads):
            events = threads[thread_id]
            sheet_id, standing_terms = standing(events)
            std = standard_terms(events)
            out.append(
                f"\nTHREAD {thread_id}: status {latest(events).get('status')}, "
                f"standing {sheet_id} "
                f"{json.dumps(standing_terms)}; standard terms {json.dumps(std)}"
            )
            for message in events[-5:]:
                head = {k: message.get(k) for k in ("status", "term_sheets", "missing_fields", "claim_results") if message.get(k)}
                out.append(f"--- {message.get('from')}: {json.dumps(head, ensure_ascii=False)}\n{message.get('body', '')[:800]}")
                for att in message.get("attachments") or []:
                    out.append(f"[attachment {att.get('name')}]\n{att.get('text', '')[:1500]}")
        return "\n".join(out)

    def draft(self, prompt, target, ceiling):
        try:
            data = parse(self.complete(SYSTEM, prompt))
            if not isinstance(data, dict):
                raise ValueError("model response is not an object")
            return {
                "analysis": str(data.get("analysis", "")),
                "data_rebuttal": str(data.get("data_rebuttal", "")),
                "target_price": target,
                "walk_away_price": ceiling,
                "email_body": str(data.get("email_body", data.get("body", ""))).strip(),
                "subject": data.get("subject"),
            }
        except Exception as exc:  # the state machine still works if the model is slow or broken
            log.warning("LLM drafting failed (%s) - using a grounded email template", exc)
            return {
                "analysis": "Use the Python-calculated offer and verified case evidence.",
                "data_rebuttal": "",
                "target_price": target,
                "walk_away_price": ceiling,
                "email_body": "How are we supposed to absorb this without shifting volume? Could you share an itemized cost breakdown and explain where you have flexibility?",
            }

    def compose_email(self, draft, data_line, history_line, peer, terms, opening_line=""):
        parts = [opening_line] if opening_line else []
        if data_line:
            parts.append(data_line)
        if history_line:
            parts.append(history_line)
        if peer:
            if peer["live"]:
                comparison = f"We have a competing offer at EUR {peer['unit_price']:.2f}/unit"
            else:
                comparison = f"Our documented alternative is EUR {peer['unit_price']:.2f}/unit"
            if peer.get("offer_id"):
                comparison += f" ({peer['offer_id']})"
            parts.append(f"{comparison}; can you improve on EUR {terms['unit_price']:.2f}/unit?")
        else:
            parts.append(f"Our counteroffer is EUR {terms['unit_price']:.2f}/unit on the attached terms.")
        draft_body = str(draft.get("email_body") or "")
        if re.search(
            r"\b(?:budget|BATNA|walk[ -]?away|target price|price ceiling|threshold|maximum|ceiling|cap|urgenc\w*|urgent|"
            r"deadline|time[ -]sensitive|time pressure|time is of the essence|promptly|expedite|"
            r"as soon as possible|at your earliest|maximum we can pay|willing to pay)\b"
            r"|(?:EUR|€)\s*\d|\d+(?:[.,]\d+)?\s*%",
            draft_body,
            flags=re.IGNORECASE,
        ) or re.search(r"\d|[$]", draft_body):
            draft_body = "Could you share an itemized cost breakdown and explain where there is flexibility?"
        if draft_body:
            room = max(15, 120 - len(" ".join(parts).split()))
            parts.append(" ".join(draft_body.split()[:room]))
        else:
            parts.append("How are we supposed to absorb this without shifting volume? Could you share an itemized cost breakdown?")
        body = " ".join(" ".join(part.split()) for part in parts)
        words = body.split()
        return " ".join(words[:120])

    def filter_ids(self, case, threads, body):
        offers = {standing(events)[0] for events in threads.values() if standing(events)[0]}

        def known(match):
            ref = match.group(0)
            if ref in offers or self.fact(case, ref):
                return ref
            log.warning("dropped unknown data ID %s", ref)
            return ""

        return re.sub(r"\s*\(\s*[,;\s]*\)", "", ID_RE.sub(known, body)).strip()


def parse(text):
    """Read the first JSON object, tolerating code fences and leading commentary."""
    decoder = json.JSONDecoder()
    for match in re.finditer(r"\{", text):
        try:
            value, _ = decoder.raw_decode(text[match.start():])
            if isinstance(value, dict):
                return value
        except json.JSONDecodeError:
            continue
    raise ValueError(f"no JSON object in reply: {text[:200]}")

