        # Round 3 is the last sensible checkpoint before another counter: close the thread
        # when its valid standing quote is already more expensive than our best alternative.
        if (
            turn >= 2
            and state["sheet_id"]
            and state["valid"]
            and state["cost"] > batnas[sid]["cost"] + 0.01
        ):
