                )
            # With no historical contract row, keep the approximately year-over-year comparison.
            if start is None and not contract_dates:
                start = rows[0]
            end_year, end_month = self._year_month(end.get("month", ""))
            if start is not None and not contract_dates and end_year is not None:
                target = end_year * 12 + end_month - 12
                start = min(
                    rows[:-1],
